import React, { useState, useEffect } from 'react';
// All CSS is now inlined for self-contained execution

// Main App Component
const App = () => {
  // Mock data for food categories and items
  const foodCategories = [
    {
      id: 'pizzas',
      name: 'Pizzas',
      items: [
        { id: 'pizza1', name: 'Margherita Pizza', price: 12.99, image: 'https://placehold.co/300x200/FF5733/FFFFFF?text=Margherita' },
        { id: 'pizza2', name: 'Pepperoni Pizza', price: 14.50, image: 'https://placehold.co/300x200/C70039/FFFFFF?text=Pepperoni' },
        { id: 'pizza3', name: 'Veggie Supreme', price: 13.75, image: 'https://placehold.co/300x200/FFC300/333333?text=Veggie' },
        { id: 'pizza4', name: 'BBQ Chicken', price: 15.25, image: 'https://placehold.co/300x200/DAF7A6/333333?text=BBQ+Chicken' },
        { id: 'pizza5', name: 'Hawaiian Pizza', price: 13.99, image: 'https://placehold.co/300x200/FF5733/FFFFFF?text=Hawaiian' },
      ],
    },
    {
      id: 'burgers',
      name: 'Burgers',
      items: [
        { id: 'burger1', name: 'Classic Burger', price: 9.99, image: 'https://placehold.co/300x200/FFC300/333333?text=Classic+Burger' },
        { id: 'burger2', name: 'Cheeseburger', price: 10.50, image: 'https://placehold.co/300x200/C70039/FFFFFF?text=Cheeseburger' },
        { id: 'burger3', name: 'Spicy Chicken Burger', price: 11.25, image: 'https://placehold.co/300x200/FF5733/FFFFFF?text=Spicy+Chicken' },
        { id: 'burger4', name: 'Veggie Burger', price: 9.75, image: 'https://placehold.co/300x200/DAF7A6/333333?text=Veggie+Burger' },
      ],
    },
    {
      id: 'desserts',
      name: 'Desserts',
      items: [
        { id: 'dessert1', name: 'Chocolate Lava Cake', price: 7.99, image: 'https://placehold.co/300x200/6A050B/FFFFFF?text=Lava+Cake' },
        { id: 'dessert2', name: 'New York Cheesecake', price: 6.50, image: 'https://placehold.co/300x200/FFC300/333333?text=Cheesecake' },
        { id: 'dessert3', name: 'Ice Cream Sundae', price: 5.25, image: 'https://placehold.co/300x200/FF5733/FFFFFF?text=Sundae' },
      ],
    },
  ];

  // State to manage cart items (simple example)
  const [cartItems, setCartItems] = useState({});

  // Function to update item quantity in cart
  const updateQuantity = (itemId, newQuantity) => {
    setCartItems(prevItems => {
      const updatedItems = { ...prevItems };
      if (newQuantity <= 0) {
        delete updatedItems[itemId]; // Remove if quantity is 0 or less
      } else {
        updatedItems[itemId] = newQuantity;
      }
      return updatedItems;
    });
  };

  // Calculate total items in cart for display
  const totalCartItems = Object.values(cartItems).reduce((sum, qty) => sum + qty, 0);

  // Profile Icon Component
  const ProfileIcon = () => (
    <div className="profile-icon-container">
      {/* User icon - using inline SVG for simplicity and consistency */}
      <svg
        xmlns="http://www.w3.org/2000/svg"
        viewBox="0 0 24 24"
        fill="currentColor"
        className="profile-icon-svg"
      >
        <path
          fillRule="evenodd"
          d="M7.5 6a4.5 4.5 0 1 1 9 0a4.5 4.5 0 0 1-9 0ZM3.751 20.105a8.25 8.25 0 0 1 16.498 0 .75.75 0 0 1-.437.695A18.683 18.683 0 0 1 12 22.5c-2.786 0-5.433-.608-7.812-1.7a.75.75 0 0 1-.437-.695Z"
          clipRule="evenodd"
        />
      </svg>
      {/* Tooltip/Dropdown for "View Profile" */}
      <div className="profile-tooltip">
        <a href="#" className="profile-tooltip-link">
          View Profile
        </a>
      </div>
    </div>
  );

  // Header Component
  const Header = () => (
    <header className="app-header">
      <div className="header-content">
        {/* Website Name/Logo */}
        <h1 className="app-logo">
          Hunger Hub
        </h1>
        {/* Search Bar */}
        <div className="search-bar-container">
          <input
            type="text"
            placeholder="Search for food..."
            className="search-input"
          />
          {/* Search Icon */}
          <svg
            xmlns="http://www.w3.org/2000/svg"
            fill="none"
            viewBox="0 0 24 24"
            strokeWidth={2}
            stroke="currentColor"
            className="search-icon"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              d="m21 21-5.197-5.197m0 0A7.5 7.5 0 1 0 5.196 5.196a7.5 7.5 0 0 0 10.607 10.607Z"
            />
          </svg>
        </div>
      </div>
      {/* Profile Icon */}
      <ProfileIcon />
    </header>
  );

  // Sidebar Component
  const Sidebar = () => (
    <aside className="app-sidebar">
      <div>
        <h2 className="sidebar-title">Explore</h2>
        <nav>
          <ul>
            <li className="sidebar-list-item">
              <a
                href="#"
                className="sidebar-link"
              >
                {/* Category Icon */}
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  fill="none"
                  viewBox="0 0 24 24"
                  strokeWidth={2}
                  stroke="currentColor"
                  className="sidebar-icon orange-icon"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    d="M9.53 16.122a3 3 0 0 0-5.78 1.128 2.25 2.25 0 0 1-2.494-2.478c.357-1.452-.364-2.891-1.995-3.658L1.1 9.874l4.26-.96a4.5 4.5 0 0 0 2.433-4.373C7.75 2.901 9.663 1.5 12 1.5s4.25 1.401 4.507 3.001a4.5 4.5 0 0 0 2.433 4.373l4.26.96-1.64 1.64a2.25 2.25 0 0 1-2.494 2.478 3 3 0 0 0-5.78-1.128 3 3 0 0 0-5.78 1.128Z"
                  />
                </svg>
                <span>Categories</span>
              </a>
            </li>
            <li className="sidebar-list-item">
              <a
                href="#"
                className="sidebar-link"
              >
                {/* Heart Icon */}
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  viewBox="0 0 24 24"
                  fill="currentColor"
                  className="sidebar-icon red-icon"
                >
                  <path d="m11.645 20.917-7.397-7.397 1.414-1.414L12 18.12l5.94-5.94 1.414 1.414-7.398 7.397Z" />
                  <path d="M12 6.042A3.5 3.5 0 0 0 8.5 2.5a3.5 3.5 0 0 0-3.5 3.5v1.5A3.5 3.5 0 0 0 8.5 11h3.5v7.5l7.397-7.397-1.416-1.414L12 15.12V6.042Z" />
                </svg>
                <span>Favorite List</span>
              </a>
            </li>
          </ul>
        </nav>
      </div>
      {/* Cart Option and Proceed to Pay button at the bottom */}
      <div className="cart-payment-section">
        <a
          href="#"
          className="cart-button"
        >
          {/* Shopping Cart Icon */}
          <svg
            xmlns="http://www.w3.org/2000/svg"
            fill="none"
            viewBox="0 0 24 24"
            strokeWidth={2}
            stroke="currentColor"
            className="cart-icon-svg"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              d="M2.25 3h1.386c.51 0 .955.343 1.023.828L5.58 15.322a2.25 2.25 0 0 0 2.247 2.179H16.25a2.25 2.25 0 0 0 2.247-2.179L21.58 6.5H3.257M15 12h6m-3 3v-6"
            />
          </svg>
          <span>Cart</span>
          {totalCartItems > 0 && (
            <span className="cart-item-count animate-bounce-slow">
              {totalCartItems}
            </span>
          )}
        </a>
        {totalCartItems > 0 && ( // Only show "Proceed to Pay" if items are in cart
          <button
            onClick={() => alert('Proceeding to payment! (This is a placeholder action)')}
            className="proceed-to-pay-button"
          >
            {/* Payment Icon */}
            <svg
              xmlns="http://www.w3.org/2000/svg"
              fill="none"
              viewBox="0 0 24 24"
              strokeWidth={2}
              stroke="currentColor"
              className="payment-icon-svg"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                d="M2.25 8.25h19.5M2.25 9h19.5m-16.5 5.25h6m-6 2.25h3m-3.75 3.75h15.375a2.25 2.25 0 0 0 2.25-2.25V6.75A2.25 2.25 0 0 0 19.5 4.5H4.5A2.25 2.25 0 0 0 2.25 6.75v10.5A2.25 2.25 0 0 0 4.5 19.5Z"
              />
            </svg>
            <span>Proceed to Pay</span>
          </button>
        )}
      </div>
    </aside>
  );

  // Food Card Component
  const FoodCard = ({ item, updateQuantity, quantityInCart }) => {
    return (
      <div className="food-card">
        <img
          src={item.image}
          alt={item.name}
          className="food-card-image"
          onError={(e) => {
            e.target.onerror = null; // prevents infinite loop
            e.target.src = `https://placehold.co/300x200/CCCCCC/333333?text=Image+Error`; // Fallback image
          }}
        />
        <div className="food-card-content">
          <h3 className="food-card-name">{item.name}</h3>
          <p className="food-card-price">${item.price.toFixed(2)}</p>
          <div className="quantity-controls">
            <button
              onClick={() => updateQuantity(item.id, quantityInCart - 1)}
              className="quantity-button minus-button"
            >
              -
            </button>
            <span className="quantity-display">
              {quantityInCart}
            </span>
            <button
              onClick={() => updateQuantity(item.id, quantityInCart + 1)}
              className="quantity-button plus-button"
            >
              +
            </button>
          </div>
        </div>
      </div>
    );
  };

  // Food Section Component (for horizontal scrolling)
  const FoodSection = ({ category, updateQuantity, cartItems }) => (
    <section className="food-section">
      <h2 className="food-section-title">
        {category.name}
      </h2>
      <div className="food-items-container scrollbar-hide">
        {category.items.map((item) => (
          <FoodCard
            key={item.id}
            item={item}
            updateQuantity={updateQuantity}
            quantityInCart={cartItems[item.id] || 0}
          />
        ))}
      </div>
    </section>
  );

  return (
    <div className="app-container">
      {/* Font Inter CDN */}
      <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700;800&display=swap" rel="stylesheet" />

      {/* Custom CSS */}
      <style>{`
        /* Global Styles */
        body {
          margin: 0;
          font-family: 'Inter', sans-serif;
          color: #374151; /* gray-800 */
        }

        .app-container {
          min-height: 100vh;
          background-color: #FFFBEB; /* yellow-50 */
          display: flex;
          flex-direction: column;
        }

        /* Header Styles */
        .app-header {
          background: linear-gradient(to right, #DC2626, #F97316); /* red-700 to orange-600 */
          color: #FFFFFF;
          padding: 1rem;
          box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05); /* shadow-xl */
          display: flex;
          align-items: center;
          justify-content: space-between;
          border-bottom-left-radius: 2rem; /* rounded-b-3xl */
          border-bottom-right-radius: 2rem; /* rounded-b-3xl */
          transform: translateY(0);
          transition: transform 0.3s ease-in-out;
        }

        .app-header:hover {
          transform: translateY(0); /* Adjusted hover to match the -translate-y-1 effect */
        }

        .header-content {
          display: flex;
          align-items: center;
          gap: 1rem; /* space-x-4 */
        }

        .app-logo {
          font-size: 2.25rem; /* text-3xl */
          font-weight: 800; /* font-extrabold */
          letter-spacing: 0.05em; /* tracking-wide */
          text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.3); /* text-shadow-md */
        }

        @media (min-width: 640px) { /* sm: breakpoint */
          .app-logo {
            font-size: 2.5rem; /* sm:text-4xl */
          }
        }

        .search-bar-container {
          position: relative;
          flex-grow: 1;
          max-width: 28rem; /* max-w-md */
        }

        .search-input {
          width: 100%;
          padding: 0.5rem 1rem 0.5rem 2.5rem; /* py-2 pl-10 pr-4 */
          border-radius: 9999px; /* rounded-full */
          background-color: rgba(255, 255, 255, 0.9); /* bg-white bg-opacity-90 */
          color: #1F2937; /* gray-800 */
          color: #6B7280; /* placeholder-gray-500 */
          border: none;
          outline: none;
          box-shadow: inset 0 2px 4px 0 rgba(0, 0, 0, 0.06); /* shadow-inner */
          transition: all 0.2s ease-in-out;
        }

        .search-input:focus {
          outline: none;
          box-shadow: 0 0 0 4px rgba(251, 191, 36, 0.75); /* focus:ring-4 focus:ring-orange-300 focus:ring-opacity-75 */
        }

        .search-icon {
          width: 1.25rem; /* w-5 */
          height: 1.25rem; /* h-5 */
          position: absolute;
          left: 0.75rem; /* left-3 */
          top: 50%;
          transform: translateY(-50%);
          color: #6B7280; /* text-gray-500 */
        }

        /* Profile Icon Styles */
        .profile-icon-container {
          position: relative;
          cursor: pointer;
          padding: 0.5rem; /* p-2 */
          border-radius: 9999px; /* rounded-full */
          background-color: #F97316; /* orange-500 */
          transition: all 0.3s ease-in-out;
          box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -2px rgba(0, 0, 0, 0.06); /* shadow-md */
        }

        .profile-icon-container:hover {
          background-color: #EA580C; /* orange-600 */
          box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05); /* hover:shadow-lg */
        }

        .profile-icon-svg {
          width: 1.5rem; /* w-6 */
          height: 1.5rem; /* h-6 */
          color: #FFFFFF;
        }

        .profile-tooltip {
          position: absolute;
          right: 0;
          margin-top: 0.5rem; /* mt-2 */
          width: 8rem; /* w-32 */
          background-color: #FFFFFF;
          border-radius: 0.375rem; /* rounded-md */
          box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05); /* shadow-lg */
          padding-top: 0.25rem; /* py-1 */
          padding-bottom: 0.25rem; /* py-1 */
          opacity: 0;
          visibility: hidden;
          transition: opacity 0.2s ease-in-out, transform 0.2s ease-in-out;
          z-index: 10;
          transform: translateY(0.5rem); /* translate-y-2 */
        }

        .profile-icon-container:hover .profile-tooltip {
          opacity: 1;
          visibility: visible;
          transform: translateY(0);
        }

        .profile-tooltip-link {
          display: block;
          padding: 0.5rem 1rem; /* px-4 py-2 */
          font-size: 0.875rem; /* text-sm */
          color: #374151; /* gray-700 */
          text-decoration: none;
          border-radius: 0.375rem; /* rounded-md */
          transition: background-color 0.15s ease-in-out;
        }

        .profile-tooltip-link:hover {
          background-color: #FFEDD5; /* orange-100 */
        }

        /* Sidebar Styles */
        .app-sidebar {
          width: 16rem; /* w-64 */
          background-color: #FFFBEB; /* yellow-100 */
          padding: 1.5rem; /* p-6 */
          box-shadow: 10px 0 15px -3px rgba(0, 0, 0, 0.1), 4px 0 6px -2px rgba(0, 0, 0, 0.05); /* shadow-2xl */
          border-top-right-radius: 2rem; /* rounded-r-3xl */
          border-bottom-right-radius: 2rem; /* rounded-r-3xl */
          display: flex;
          flex-direction: column;
          justify-content: space-between;
          transform: translateX(0);
          transition: transform 0.3s ease-in-out;
        }

        .app-sidebar:hover {
          transform: translateX(0); /* Adjusted hover to match the -translate-x-1 effect */
        }

        .sidebar-title {
          font-size: 1.5rem; /* text-2xl */
          font-weight: 700; /* font-bold */
          color: #C2410C; /* orange-800 */
          margin-bottom: 1.5rem; /* mb-6 */
          border-bottom: 2px solid #FDBA74; /* border-b-2 border-orange-300 */
          padding-bottom: 0.5rem; /* pb-2 */
        }

        .sidebar-list-item {
          margin-bottom: 1rem; /* mb-4 */
        }

        .sidebar-link {
          display: flex;
          align-items: center;
          gap: 0.75rem; /* space-x-3 */
          color: #374151; /* gray-800 */
          text-decoration: none;
          font-weight: 600; /* font-semibold */
          font-size: 1.125rem; /* text-lg */
          transition: all 0.2s ease-in-out;
          padding: 0.75rem; /* p-3 */
          border-radius: 0.75rem; /* rounded-xl */
          transform: scale(1);
        }

        .sidebar-link:hover {
          color: #EA580C; /* orange-700 */
          background-color: #FEE7B6; /* yellow-200 */
          transform: scale(1.05);
        }

        .sidebar-icon {
          width: 1.5rem; /* w-6 */
          height: 1.5rem; /* h-6 */
        }

        .orange-icon {
          color: #F97316; /* orange-500 */
        }

        .red-icon {
          color: #EF4444; /* red-500 */
        }

        /* Cart and Payment Section */
        .cart-payment-section {
          margin-top: auto; /* mt-auto */
          display: flex;
          flex-direction: column;
          gap: 1rem; /* space-y-4 */
        }

        .cart-button, .proceed-to-pay-button {
          display: flex;
          align-items: center;
          justify-content: center;
          gap: 0.75rem; /* space-x-3 for cart, space-x-2 for pay */
          font-weight: 700; /* font-bold */
          padding: 0.75rem 1rem; /* py-3 px-4 */
          border-radius: 9999px; /* rounded-full */
          box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05); /* shadow-lg */
          transition: all 0.3s ease-in-out;
          position: relative;
          text-decoration: none; /* For the <a> tag */
          transform: scale(1);
          border: none; /* Remove default button border */
          cursor: pointer; /* Ensure button is clickable */
        }

        .cart-button {
          background-color: #F97316; /* orange-600 */
          color: #FFFFFF;
        }

        .cart-button:hover {
          background-color: #EA580C; /* orange-700 */
          transform: scale(1.05);
        }

        .proceed-to-pay-button {
          background-color: #16A34A; /* green-600 */
          color: #FFFFFF;
        }

        .proceed-to-pay-button:hover {
          background-color: #15803D; /* green-700 */
          transform: scale(1.05);
        }

        .cart-icon-svg, .payment-icon-svg {
          width: 1.5rem; /* w-6 */
          height: 1.5rem; /* h-6 */
          color: #FFFFFF;
        }

        .cart-item-count {
          position: absolute;
          top: -0.5rem; /* -top-2 */
          right: -0.5rem; /* -right-2 */
          background-color: #991B1B; /* red-800 */
          color: #FFFFFF;
          font-size: 0.75rem; /* text-xs */
          font-weight: 700; /* font-bold */
          border-radius: 9999px; /* rounded-full */
          height: 1.5rem; /* h-6 */
          width: 1.5rem; /* w-6 */
          display: flex;
          align-items: center;
          justify-content: center;
          animation: bounce-slow 1.5s infinite;
        }

        /* Food Card Styles */
        .food-card {
          flex-shrink: 0;
          width: 16rem; /* w-64 */
          background-color: #FFFFFF;
          border-radius: 0.75rem; /* rounded-xl */
          box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05); /* shadow-lg */
          transition: all 0.3s ease-in-out;
          overflow: hidden;
          margin: 1rem; /* m-4 */
          border: 1px solid #F3F4F6; /* border border-gray-100 */
          transform: translateY(0) scale(1);
        }

        .food-card:hover {
          box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 8px 10px -6px rgba(0, 0, 0, 0.05); /* hover:shadow-xl */
          transform: translateY(-0.5rem) scale(1.05); /* hover:-translate-y-2 hover:scale-105 */
        }

        .food-card-image {
          width: 100%;
          height: 9rem; /* h-36 */
          object-fit: cover;
          border-top-left-radius: 0.75rem; /* rounded-t-lg */
          border-top-right-radius: 0.75rem; /* rounded-t-lg */
        }

        .food-card-content {
          padding: 1rem; /* p-4 */
        }

        .food-card-name {
          font-size: 1.25rem; /* text-xl */
          font-weight: 600; /* font-semibold */
          color: #1F2937; /* gray-800 */
          margin-bottom: 0.25rem; /* mb-1 */
        }

        .food-card-price {
          color: #EA580C; /* orange-600 */
          font-weight: 700; /* font-bold */
          font-size: 1.125rem; /* text-lg */
          margin-bottom: 0.75rem; /* mb-3 */
        }

        .quantity-controls {
          display: flex;
          align-items: center;
          justify-content: space-between;
          background-color: #FFF7ED; /* orange-50 */
          border-radius: 9999px; /* rounded-full */
          padding: 0.25rem; /* p-1 */
        }

        .quantity-button {
          border-radius: 9999px; /* rounded-full */
          width: 2rem; /* w-8 */
          height: 2rem; /* h-8 */
          display: flex;
          align-items: center;
          justify-content: center;
          font-size: 1.25rem; /* text-xl */
          font-weight: 700; /* font-bold */
          transition: all 0.2s ease-in-out;
          border: none;
          cursor: pointer;
          outline: none;
        }

        .minus-button {
          background-color: #FED7AA; /* orange-200 */
          color: #9A3412; /* orange-800 */
        }

        .minus-button:hover {
          background-color: #FDBA74; /* orange-300 */
        }

        .minus-button:focus {
          outline: none;
          box-shadow: 0 0 0 2px #FDBA74; /* focus:ring-2 focus:ring-orange-400 */
        }

        .minus-button:active {
          background-color: #FDBA74; /* active:bg-orange-400 */
          color: #FFFFFF; /* active:text-white */
        }

        .plus-button {
          background-color: #EA580C; /* orange-600 */
          color: #FFFFFF;
        }

        .plus-button:hover {
          background-color: #C2410C; /* orange-700 */
        }

        .plus-button:focus {
          outline: none;
          box-shadow: 0 0 0 2px #FDBA74; /* focus:ring-2 focus:ring-orange-400 */
        }

        .plus-button:active {
          background-color: #9A3412; /* active:bg-orange-800 */
        }

        .quantity-display {
          font-size: 1.25rem; /* text-xl */
          font-weight: 700; /* font-bold */
          color: #C2410C; /* orange-700 */
          margin: 0 0.5rem; /* mx-2 */
        }

        /* Food Section Styles */
        .food-section {
          margin-bottom: 2rem; /* mb-8 */
        }

        .food-section-title {
          font-size: 1.875rem; /* text-3xl */
          font-weight: 700; /* font-bold */
          color: #C2410C; /* orange-800 */
          margin-bottom: 1.5rem; /* mb-6 */
          padding-left: 1rem; /* px-4 */
          border-bottom: 2px solid #FDBA74; /* border-b-2 border-orange-300 */
          padding-bottom: 0.5rem; /* pb-2 */
        }

        .food-items-container {
          display: flex;
          overflow-x: auto;
          padding-bottom: 1rem; /* pb-4 */
        }

        /* Custom scrollbar styling */
        .scrollbar-hide::-webkit-scrollbar {
          display: none;
        }
        .scrollbar-hide {
          -ms-overflow-style: none;  /* IE and Edge */
          scrollbar-width: none;  /* Firefox */
        }

        /* Custom bounce animation for cart items */
        @keyframes bounce-slow {
          0%, 100% {
            transform: translateY(0);
          }
          50% {
            transform: translateY(-8px);
          }
        }
        .animate-bounce-slow {
          animation: bounce-slow 1.5s infinite;
        }
      `}</style>

      <Header />
      <div className="main-content-area">
        <Sidebar />
        <main className="main-food-display">
          {foodCategories.map((category) => (
            <FoodSection
              key={category.id}
              category={category}
              updateQuantity={updateQuantity}
              cartItems={cartItems}
            />
          ))}
        </main>
      </div>
    </div>
  );
};

export default App;
